WITH parsed AS (SELECT id, effective_from, currency, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT currency, CASE WHEN lowest_price >= 35 THEN 'HIGH' ELSE 'LOW' END AS lowest_price_tier, SUM(lowest_price) FILTER (WHERE currency = 'THB') AS thb_total_lowest_price, AVG(lowest_price) FILTER (WHERE currency = 'THB') AS thb_avg_lowest_price, SIZE(COLLECT_SET(currency)) AS num_currencies, GROUPING(currency) AS grouping_id FROM parsed GROUP BY GROUPING SETS ((currency, CASE WHEN lowest_price >= 35 THEN 'HIGH' ELSE 'LOW' END), (currency));
